CREATE TABLE fraud_rule (id UUID PRIMARY KEY, name VARCHAR(120) NOT NULL UNIQUE, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE TABLE rule_version (id UUID PRIMARY KEY, rule_id UUID NOT NULL REFERENCES fraud_rule(id), version_no INTEGER NOT NULL, status VARCHAR(16) NOT NULL, action VARCHAR(16) NOT NULL CHECK(action IN ('BLOCK','REVIEW')), priority INTEGER NOT NULL, condition_json JSONB NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now(), UNIQUE(rule_id,version_no));
CREATE INDEX idx_rule_version_status_priority ON rule_version(status,priority);
CREATE TABLE ruleset_state (id INTEGER PRIMARY KEY CHECK(id=1), version BIGINT NOT NULL);
CREATE TABLE evaluation_log (id UUID PRIMARY KEY, transaction_id VARCHAR(160) NOT NULL UNIQUE, decision VARCHAR(16) NOT NULL CHECK(decision IN ('BLOCK','REVIEW','ALLOW')), ruleset_version BIGINT NOT NULL, matched_rules JSONB NOT NULL, request_payload JSONB NOT NULL, evaluation_micros BIGINT NOT NULL, created_at TIMESTAMPTZ NOT NULL DEFAULT now());
CREATE INDEX idx_evaluation_log_created_at ON evaluation_log(created_at DESC);
